import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";var i=JSON.parse(`{"title":"REST API","description":"","frontmatter":{},"headers":[],"relativePath":"content/plugins/bcew-document-repository/developer/rest-api.md","filePath":"content/plugins/bcew-document-repository/developer/rest-api.md"}`),a={name:`content/plugins/bcew-document-repository/developer/rest-api.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to “REST API”">​</a></h1><p>Namespace comes from <code>RepositoryConfig::get_api_namespace</code> in <code>src/RepositoryConfig.php</code> (default: <code>bcew-document-repository/v1</code>).</p><ul><li>GET <code>/{namespace}/documents</code> — the REST default is <code>publish</code>, but only <code>trash</code> selects a distinct result set. <code>trash</code> returns trashed documents; <code>publish</code>, <code>draft</code>, <code>any</code>, <code>all</code>, and other values return all non-trashed documents (<code>publish</code>, <code>draft</code>, <code>pending</code>, and <code>private</code>).</li><li>POST <code>/{namespace}/documents</code> — uploads a PDF and creates a document post with metadata.</li><li>GET <code>/{namespace}/documents/check-duplicate?search_name={filename}</code> — checks duplicate original filenames.</li><li>GET <code>/{namespace}/documents/{id}</code> — fetches a single document.</li></ul><p>See <code>src/RestApiController.php</code>. Requests use the <code>wp_rest</code> nonce and the capability from <code>RepositoryConfig::get_capability</code> (default: <code>upload_files</code>).</p>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};